"use client";

import { loadFont } from "@remotion/google-fonts/InstrumentSans";
import {
  type CSSProperties,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  Img,
  interpolate,
  spring,
  staticFile,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround, gshParams } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_CAPTIONS,
  DEFAULT_IMAGES,
  imagesOf,
  type WordGapMediaElementId,
  wordGapMediaTimeline,
} from "./timeline";

const sans = loadFont("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface WordGapMediaProps {
  before?: string;
  after?: string;
  images?: string[];
  aspects?: number[];
  captions?: string[];
  accent?: string;
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Instrument Sans by default. */
  fontFamily?: string;
  /** Frames between words as each side builds. */
  stagger?: number;
  /** Size of the line and tile, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /**
   * Moves, trims or stretches the words, the card opening, each image swap
   * and the settle, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<WordGapMediaElementId>;
}

const LIGHT_GROUND: Partial<GradientParams> = {
  kind: "smear",
  background: "#efe8dc",
  colors: ["#f6b48c", "#f7d39a", "#eab3cc", "#cfdccf"],
  blur: 0.7,
  seed: 6,
  grain: 0.18,
};

const THEMES = {
  dark: {
    ink: "#f2f0fb",
    accent: "#3B5BFD",
    ground: "velvet-hour" as GshPresetId | undefined,
    groundParams: undefined as Partial<GradientParams> | undefined,
    groundOffset: 6,
    scrim: "4,4,14",
    scrimAlpha: 0.42,
    border: "rgba(255,255,255,0.14)",
    highlight: "inset 0 1px 0 rgba(255,255,255,0.18)",
    shadow:
      "0 1px 2px rgba(2,3,12,0.4), 0 12px 28px rgba(2,3,12,0.45), 0 48px 96px rgba(2,3,12,0.55)",
    base: "#141833",
  },
  light: {
    ink: "#1a1714",
    accent: "#f2552c",
    ground: undefined as GshPresetId | undefined,
    groundParams: LIGHT_GROUND as Partial<GradientParams> | undefined,
    groundOffset: 3,
    scrim: "244,238,228",
    scrimAlpha: 0.5,
    border: "rgba(40,28,16,0.10)",
    highlight: "inset 0 1px 0 rgba(255,255,255,0.35)",
    shadow:
      "0 1px 2px rgba(80,50,20,0.10), 0 10px 24px rgba(80,50,20,0.14), 0 40px 80px rgba(80,50,20,0.18)",
    base: "#e3dacb",
  },
};

const DEFAULT_ASPECTS = [0.8, 1.36, 1.0, 0.86];

const TRACK = -0.035;
const FONT_PX = 200;
const ENTER = Easing.bezier(0.22, 1, 0.36, 1);
const WIPE = Easing.bezier(0.83, 0, 0.17, 1);
const LABEL_IN = Easing.bezier(0.32, 0.72, 0, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

type Measure = (s: string) => number;

function buildMeasure(_version: number, fontFamily: string): Measure {
  const ctx = document.createElement("canvas").getContext("2d");
  const cache: Record<string, number> = {};
  return (s: string) => {
    if (cache[s] === undefined) {
      if (!ctx) return s.length * 0.55;
      ctx.font = `400 ${FONT_PX}px "${fontFamily}"`;
      cache[s] =
        ctx.measureText(s).width / FONT_PX + TRACK * Array.from(s).length;
    }
    return cache[s];
  };
}

function useMeasure(fontFamily: string) {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("word-gap-media: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      sans.waitUntilDone(),
      document.fonts.load(`400 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle, fontFamily]);
  return useMemo(
    () => buildMeasure(version, fontFamily),
    [version, fontFamily],
  );
}

function resolveSrc(src: string) {
  return /^(https?:|data:|\/)/.test(src) ? src : staticFile(src);
}

function Words({
  text,
  spans,
  t,
  style,
}: {
  text: string;
  /** Each word's rise, from the schedule. */
  spans: { start: number; end: number }[];
  t: number;
  style: CSSProperties;
}) {
  const parts = text.split(" ").filter(Boolean);
  return (
    <div style={{ display: "flex", whiteSpace: "pre", ...style }}>
      {parts.map((w, i) => {
        const span = spans[i];
        const e = interpolate(t, [span.start, span.end], [0, 1], {
          ...CLAMP,
          easing: ENTER,
        });
        return (
          <span
            key={`${w}${i}`}
            style={{
              display: "inline-block",
              clipPath: "inset(-40% -20% -0.24em -20%)",
              marginRight: i < parts.length - 1 ? "0.24em" : 0,
            }}
          >
            <span
              style={{
                display: "inline-block",
                transform: `translateY(${((1 - e) * 0.7).toFixed(4)}em)`,
                opacity: e,
                filter:
                  e < 1 ? `blur(${((1 - e) * 6).toFixed(2)}px)` : undefined,
              }}
            >
              {w}
            </span>
          </span>
        );
      })}
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function WordGapMedia(props: WordGapMediaProps) {
  const {
    before = "Launch all",
    after = "of this",
    images = DEFAULT_IMAGES,
    aspects = DEFAULT_ASPECTS,
    captions = DEFAULT_CAPTIONS,
    accent,
    ink,
    background,
    fontFamily = sans.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    ground,
    groundParams,
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    wordGapMediaTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const inkC = ink ?? c.ink;
  const hi = accent ?? c.accent;
  const preset = ground ?? (groundParams ? undefined : c.ground);
  const gParams = groundParams ?? (ground ? undefined : c.groundParams);
  const bg = background ?? gshParams(preset, gParams).background;
  const m = useMeasure(fontFamily);
  const t = frame;
  const portrait = H > W * 1.1;

  const list = imagesOf(images);
  const n = list.length;
  const aspectOf = (i: number) => aspects[i % Math.max(1, aspects.length)] ?? 1;
  const openEl = tl.get("open");
  const settleEl = tl.get("settle");
  // Image 0 arrives with the card; every next one has its own swap.
  const swapEls = list.map((_, i) => (i === 0 ? openEl : tl.get(`image:${i}`)));
  const swapAt = swapEls.map((e) => e.start);
  const settleAt = settleEl.start;

  const open = Math.max(
    0,
    spring({
      frame: t - openEl.start,
      fps,
      config: { mass: 0.8, damping: 18, stiffness: 160 },
    }),
  );
  const swapP = (i: number, tt: number) =>
    i === 0
      ? 1
      : interpolate(tt, [swapEls[i].start, swapEls[i].end], [0, 1], {
          ...CLAMP,
          easing: WIPE,
        });
  const morphP = (i: number, tt: number) =>
    i === 0
      ? 1
      : spring({
          frame: tt - swapAt[i],
          fps,
          config: { damping: 200 },
          durationInFrames: swapEls[i].beat("morph"),
        });
  const aspectAt = (tt: number) => {
    let a = aspectOf(0);
    for (let i = 1; i < n; i++) a += (aspectOf(i) - a) * morphP(i, tt);
    return a;
  };
  const settle = spring({
    frame: t - settleAt,
    fps,
    config: { mass: 0.5, damping: 12, stiffness: 200 },
  });
  const punchScale = t < settleAt ? 1 : 0.965 + 0.035 * settle;

  let content: React.ReactNode = <div />;
  if (m) {
    const marginX = W * (portrait ? 0.08 : 0.07);
    const room = W - marginX * 2;
    const maxAspect = Math.max(...list.map((_, i) => aspectOf(i)));
    const minAspect = Math.min(...list.map((_, i) => aspectOf(i)));
    const gapEm = 0.34;
    let F: number;
    let cardBase: number;
    if (portrait) {
      F = Math.min(W * 0.14, room / Math.max(m(before), m(after), 0.1));
      cardBase = Math.min(W * 0.72, H * 0.54 * minAspect);
    } else {
      cardBase = H * 0.5;
      const textW = m(before) + m(after) + gapEm * 2;
      F = Math.min(
        H * 0.13,
        (room - cardBase * maxAspect) / Math.max(0.1, textW),
      );
    }

    const a = aspectAt(t);
    const aPrev = aspectAt(t - 1);
    const cardW = portrait ? cardBase : cardBase * a;
    const cardH = portrait ? cardBase / a : cardBase;
    const slotMain = (portrait ? cardH : cardW) * open;
    const slotCross =
      (portrait ? cardW : cardH) * (0.55 + 0.45 * Math.min(1, open));
    // The card's resting size: the last image's aspect, fully open. Children
    // pinned to its right or bottom edge are laid out against it and ride the
    // live size by a transform, since layout rounds a box to whole pixels and
    // a button carried by `right` while the card widens clicks across.
    const aRest = aspectOf(n - 1);
    const boxW = portrait ? slotCross : slotMain;
    const boxH = portrait ? slotMain : slotCross;
    const restW = portrait ? cardBase : cardBase * aRest;
    const restH = portrait ? cardBase / aRest : cardBase;
    const growX = boxW - restW;
    const growY = boxH - restH;
    const shift = (x: number, y: number) =>
      Math.abs(x) < 1e-3 && Math.abs(y) < 1e-3
        ? ""
        : `translate(${x}px, ${y}px) `;
    const moveSpeed = Math.abs(a - aPrev) * cardBase;
    const wordBlur = Math.min(4, moveSpeed * 0.12);
    const gap = F * Math.max(0.12, gapEm * Math.min(1.1, open));

    // The tilt runs to the clip's end, counted without `speed` as before.
    const tilt = interpolate(
      t,
      [openEl.start, durationInFrames],
      [-6, 3],
      CLAMP,
    );
    const tiltX = interpolate(Math.min(1, open), [0, 1], [14, 2]);
    const R = cardBase * 0.055;
    const pad = cardBase * 0.045;

    const imgNodes = list.map((src, i) => {
      const r = swapP(i, t);
      const out = i < n - 1 ? swapP(i + 1, t) : 0;
      if (r <= 0 || out >= 1) return null;
      const lifeEnd = swapAt[i] + swapEls[i].beat("life");
      const life = interpolate(t, [swapAt[i], lifeEnd], [1.12, 1.02], {
        ...CLAMP,
        easing: LABEL_IN,
      });
      const speed = i > 0 ? Math.abs(r - swapP(i, t - 1)) : 0;
      return (
        <div
          key={`img${i}`}
          style={{
            position: "absolute",
            inset: 0,
            clipPath:
              i === 0
                ? undefined
                : `inset(0 0 0 ${((1 - r) * 100).toFixed(2)}%)`,
            transform: `translateX(${(-out * 24).toFixed(2)}%)`,
          }}
        >
          <Img
            src={resolveSrc(src)}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              transform: `scale(${(life + (1 - r) * 0.12).toFixed(4)})`,
              filter: `brightness(${(1 - out * 0.45).toFixed(3)})${speed > 0.02 ? ` blur(${Math.min(5, speed * 40).toFixed(2)}px)` : ""}`,
            }}
          />
        </div>
      );
    });

    const barsAt = openEl.start + openEl.beat("bars");
    const barsIn = interpolate(
      t,
      [barsAt, barsAt + openEl.beat("barsIn")],
      [0, 1],
      { ...CLAMP, easing: LABEL_IN },
    );
    const barH = Math.max(3, cardBase * 0.008);
    const barGap = barH * 1.6;
    // Each bar sits where the resting card puts it and slides by its share
    // of the width change, which is what the flex row did by layout.
    const barW = (boxW - pad * 2 - barGap * (n - 1)) / n;
    const barRestW = (restW - pad * 2 - barGap * (n - 1)) / n;
    const bars = (
      <div
        style={{
          position: "absolute",
          left: pad,
          right: pad,
          top: pad,
          height: barH,
          opacity: barsIn,
          transform: `translateY(${((1 - barsIn) * -pad * 0.6).toFixed(2)}px)`,
        }}
      >
        {list.map((_, i) => {
          const from = swapAt[i];
          const to = i < n - 1 ? swapAt[i + 1] : settleAt;
          const fill = interpolate(t, [from, to], [0, 1], CLAMP);
          const slide = i * (barW - barRestW);
          return (
            <div
              key={`bar${i}`}
              style={{
                position: "absolute",
                left: i * (barRestW + barGap),
                top: 0,
                width: barW,
                transform:
                  Math.abs(slide) < 1e-3 ? undefined : `translateX(${slide}px)`,
                height: barH,
                borderRadius: barH,
                background: "rgba(255,255,255,0.32)",
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  width: `${(fill * 100).toFixed(2)}%`,
                  height: "100%",
                  background: "rgba(255,255,255,0.95)",
                }}
              />
            </div>
          );
        })}
      </div>
    );

    const capFont = Math.max(H * 0.026, cardBase * 0.06);
    const capNodes = list.map((_, i) => {
      const label = captions[i % Math.max(1, captions.length)] ?? "";
      const inAt = swapAt[i] + swapEls[i].beat("caption");
      const e = interpolate(
        t,
        [inAt, inAt + swapEls[i].beat("captionIn")],
        [0, 1],
        { ...CLAMP, easing: LABEL_IN },
      );
      const x =
        i < n - 1
          ? interpolate(
              t,
              [swapAt[i + 1], swapAt[i + 1] + swapEls[i + 1].beat("outgoing")],
              [0, 1],
              { ...CLAMP, easing: Easing.bezier(0.55, 0, 1, 0.45) },
            )
          : 0;
      if (e <= 0 || x >= 1) return null;
      return (
        <div
          key={`cap${i}`}
          style={{
            position: "absolute",
            left: pad * 1.1,
            top: restH - pad * 1.15 - capFont,
            height: capFont,
            fontFamily,
            fontWeight: 400,
            fontSize: capFont,
            lineHeight: 1,
            letterSpacing: "-0.01em",
            color: "rgba(255,255,255,0.96)",
            whiteSpace: "pre",
            clipPath: "inset(-20% -10% -20% -10%)",
            opacity: e * (1 - x),
            transform: `${shift(0, growY)}translateY(${((1 - e) * capFont * 0.8 - x * capFont * 0.6).toFixed(2)}px)`,
          }}
        >
          {label}
        </div>
      );
    });

    const btnD = Math.max(H * 0.062, cardBase * 0.14);
    const btnIn = spring({
      frame: t - (openEl.start + openEl.beat("button")),
      fps,
      config: { mass: 0.5, damping: 12, stiffness: 200 },
    });
    const armed = interpolate(
      t - settleAt,
      [0, settleEl.beat("armed")],
      [0, 1],
      {
        ...CLAMP,
        easing: LABEL_IN,
      },
    );
    const btnScale = btnIn * (t < settleAt ? 1 : 0.88 + 0.12 * settle);
    const borderHit = interpolate(
      t - settleAt,
      [0, settleEl.beat("hit"), settleEl.length],
      [0, 1, 0.4],
      CLAMP,
    );

    // The slot keeps the words reflowing as before, but its centre never
    // moves (the row is centred on both axes), while its top-left edge does,
    // and layout rounds that edge to whole pixels: every box on the card
    // clicked as it grew. The card hangs from the slot's centre instead, laid
    // out at its resting corner and carried to the live one by a transform.
    const card = (
      <div
        style={{
          position: "relative",
          width: boxW,
          height: boxH,
          flexShrink: 0,
          margin: portrait ? `${gap}px 0` : `0 ${gap}px`,
        }}
      >
        <div style={{ position: "absolute", left: "50%", top: "50%" }}>
          <div
            style={{
              position: "absolute",
              left: -restW / 2,
              top: -restH / 2,
              width: boxW,
              height: boxH,
              transform: `${shift(-growX / 2, -growY / 2)}perspective(${(H * 2).toFixed(0)}px) rotateY(${tilt.toFixed(2)}deg) rotateX(${tiltX.toFixed(2)}deg) scale(${punchScale.toFixed(4)})`,
              opacity: open > 0.001 ? 1 : 0,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius: R,
                overflow: "hidden",
                boxShadow: c.shadow,
                background: c.base,
              }}
            >
              {imgNodes}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background:
                    "linear-gradient(180deg, rgba(0,0,0,0.32) 0%, rgba(0,0,0,0) 22%, rgba(0,0,0,0) 62%, rgba(0,0,0,0.42) 100%)",
                }}
              />
              {bars}
              {capNodes}
              <div
                style={{
                  position: "absolute",
                  left: restW - pad - btnD,
                  top: restH - pad * 0.8 - btnD,
                  width: btnD,
                  height: btnD,
                  borderRadius: btnD,
                  background: `color-mix(in oklab, ${hi} ${(armed * 100).toFixed(1)}%, rgba(255,255,255,0.2))`,
                  backdropFilter: "blur(14px)",
                  boxShadow: `inset 0 0 0 1px rgba(255,255,255,${(0.38 - 0.2 * armed).toFixed(3)}), 0 ${(btnD * 0.16).toFixed(1)}px ${(btnD * 0.4).toFixed(1)}px rgba(0,0,0,${(0.12 + 0.18 * armed).toFixed(3)})`,
                  transform: `${shift(growX, growY)}scale(${btnScale.toFixed(4)})`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <svg
                  viewBox="0 0 24 24"
                  width={btnD * 0.4}
                  height={btnD * 0.4}
                  aria-hidden
                >
                  <path
                    d="M8.5 6.2v11.6c0 .6.6.9 1.1.6l9-5.8c.5-.3.5-.9 0-1.2l-9-5.8c-.5-.3-1.1 0-1.1.6z"
                    fill="#ffffff"
                  />
                </svg>
              </div>
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  borderRadius: R,
                  boxShadow: `inset 0 0 0 1px ${borderHit > 0.01 ? `color-mix(in oklab, ${hi} ${(borderHit * 100).toFixed(0)}%, ${c.border})` : c.border}, ${c.highlight}`,
                }}
              />
            </div>
          </div>
        </div>
      </div>
    );

    const textStyle: CSSProperties = {
      fontFamily,
      fontWeight: 400,
      fontSize: F,
      lineHeight: 1,
      letterSpacing: `${TRACK}em`,
      color: inkC,
      filter: wordBlur > 0.1 ? `blur(${wordBlur.toFixed(2)}px)` : undefined,
    };
    const words = tl.lane("Words");
    const beforeCount = before.split(" ").filter(Boolean).length;
    const pushAt = (f: number) =>
      interpolate(f, [0, durationInFrames], [1, 1.035], CLAMP);
    const push = pushAt(frame);
    const pushMoving =
      Math.abs(pushAt(frame + speed) - push) * (W / 2) > 1e-3 ||
      Math.abs(push - pushAt(frame - speed)) * (W / 2) > 1e-3;

    content = (
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: portrait ? "column" : "row",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${push.toFixed(5)})${glide(pushMoving)}`,
        }}
      >
        <Words
          text={before}
          spans={words.slice(0, beforeCount)}
          t={t}
          style={textStyle}
        />
        {card}
        <Words
          text={after}
          spans={words.slice(beforeCount)}
          t={t}
          style={textStyle}
        />
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      {background === undefined ? (
        <>
          <GshGround
            preset={preset}
            params={gParams}
            timeOffset={c.groundOffset}
            timeScale={0.6}
          />
          <AbsoluteFill
            style={{
              background: `radial-gradient(${portrait ? "80% 50%" : "62% 56%"} at 50% 50%, rgba(${c.scrim},${c.scrimAlpha}) 0%, rgba(${c.scrim},0) 100%)`,
            }}
          />
        </>
      ) : (
        <AbsoluteFill
          style={{
            background: background === "transparent" ? undefined : background,
          }}
        />
      )}
      <ScaleLayer scale={scale}>{content}</ScaleLayer>
    </AbsoluteFill>
  );
}

export default WordGapMedia;

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The words on both sides of the gap rising in, the card opening between
// them, each next image wiping over the one before, and the settle that
// arms the play button. Frames on the 30 fps scene timeline, after `delay`
// and `speed`. The ids are public: a saved `timing` prop refers to them.

export type WordGapMediaElementId =
  | `word:${number}`
  | "open"
  | `image:${number}`
  | "settle";

export interface WordGapMediaTimingProps {
  before?: string;
  after?: string;
  images?: string[];
  captions?: string[];
  stagger?: number;
}

export const DEFAULT_IMAGES = [
  "templates/product-showcase/sculpture.jpg",
  "templates/product-showcase/gallery.jpg",
  "templates/product-showcase/workbench.jpg",
  "templates/product-showcase/courtyard.jpg",
];
export const DEFAULT_CAPTIONS = ["Hero", "Gallery", "Detail", "Setting"];

export const WORD_STEP = 3;
const ENTER = 12;
const OPEN = 24;
const DWELL = [36, 30, 24];
const SWAP_LEN = 12;
const SETTLE_AFTER = 18;

/** The images the card shows: the first four, or the defaults when empty. */
export function imagesOf(images: string[]) {
  return (images.length > 0 ? images : DEFAULT_IMAGES).slice(0, 4);
}

// `word:<k>` counts the words of `before` and then of `after`, one chain.
// `open` springs the card open; its beats time the progress bars, the first
// caption, the button and the first image's slow zoom (`life`). `image:<i>`
// (from the second image) wipes in over `length` and morphs the card's
// aspect over `morph`; `caption` and `captionIn` bring its caption,
// `outgoing` takes the previous caption out. `settle` punches the card and
// arms the button (`armed`), flashing the border over `hit` and `length`.
export const wordGapMediaTimeline = defineTimeline<
  WordGapMediaElementId,
  WordGapMediaTimingProps
>(
  ({
    before = "Launch all",
    after = "of this",
    images = DEFAULT_IMAGES,
    captions = DEFAULT_CAPTIONS,
    stagger = WORD_STEP,
  }) => {
    const beforeWords = before.split(" ").filter(Boolean);
    const afterWords = after.split(" ").filter(Boolean);
    const afterStart = beforeWords.length * stagger;
    const words = [
      ...beforeWords.map((w, i) => ({ w, at: 0 + i * stagger - 4 })),
      ...afterWords.map((w, i) => ({ w, at: afterStart + i * stagger - 4 })),
    ];
    const n = imagesOf(images).length;
    const swapAt: number[] = [OPEN];
    for (let i = 1; i < n; i++) {
      swapAt.push(swapAt[i - 1] + DWELL[Math.min(i - 1, DWELL.length - 1)]);
    }
    const settleAt = n > 1 ? swapAt[n - 1] + SETTLE_AFTER : OPEN + SETTLE_AFTER;
    const captionOf = (i: number) =>
      captions[i % Math.max(1, captions.length)] ?? "";

    const elements: TimelineElement<WordGapMediaElementId>[] = [
      ...words.map(
        ({ w, at }, k): TimelineElement<WordGapMediaElementId> => ({
          id: `word:${k}`,
          lane: "Words",
          label: w,
          start: at,
          length: ENTER,
          follows: k > 0 ? `word:${k - 1}` : undefined,
        }),
      ),
      {
        id: "open",
        lane: "Card",
        label: captionOf(0),
        start: OPEN,
        length: 18,
        beats: {
          bars: 6,
          barsIn: 12,
          caption: 9,
          captionIn: 12,
          button: 12,
          life: 60,
        },
      },
      ...swapAt.slice(1).map(
        (at, j): TimelineElement<WordGapMediaElementId> => ({
          id: `image:${j + 1}`,
          lane: "Card",
          label: captionOf(j + 1),
          start: at,
          length: SWAP_LEN,
          follows: j > 0 ? `image:${j}` : "open",
          beats: {
            morph: 16,
            life: 60,
            caption: 4,
            captionIn: 12,
            outgoing: 8,
          },
        }),
      ),
      {
        id: "settle",
        lane: "Card",
        label: "Settle",
        start: settleAt,
        length: 20,
        follows: n > 1 ? `image:${n - 1}` : "open",
        beats: { hit: 4, armed: 6 },
      },
    ];
    return elements.sort((a, b) => a.start - b.start);
  },
);
